            while ((line = br.readLine()) != null) {
                row++;
                if (line.isEmpty()) continue;
                String[] p = line.split(",");
                Transaction t = new Transaction();
                t.rowNum = row;
                t.txId = p[0];
                t.accountId = p[1];
