                t.type = p[3];
                t.amount = new BigDecimal(p[4]);
                t.currency = p[5];
                t.effectiveDate = sdf.parse(p[6]);
                t.reversalOf = (p.length > 7 && !p[7].isEmpty()) ? p[7] : null;
