                st.execute("CREATE TABLE RUN_AUDIT (jdbc_url VARCHAR, biz_date DATE, accounts INT, valid_txs INT, skipped_txs INT, report_md5 VARCHAR)");
                String accIns = "INSERT INTO ACCOUNTS (account_id,currency,start_balance,base_apr,tier_threshold,tier_apr,promo_apr,promo_days,opened_at) VALUES (?,?,?,?,?,?,?,?,?)";
